"""Clause-opener detector for layers.15.mlp.down_proj component 2881.

What the component does: it goes strongly negative on the words that open a reported claim,
an inference or a condition, where the model is about to state a proposition. The strongest
cases are the complementizer "that" after a verb or noun of knowing, saying or evidence
("evidence that", "suggests that", "is that"), verbs of belief ("believes", "implies"),
"whether", "unless" and the conclusion words "therefore", "thus", "hence", "perhaps", "maybe".
Weaker negatives come from plain verbs of saying and subordinators ("because", "so", "if",
"when"), from commas that close a short opening phrase ("In that case,"), and from "the" that
starts an embedded clause after "if", "when", "that" and so on. "that" as a relative pronoun
or after a preposition ("of that", "things that") stays near zero, and the contrast words
"but" and "however" are mildly positive.

This program reads only the newest token and the one before it (and the start of the
current sentence for commas), and predicts the component's activation from those word
classes. It captures about 10% of the activation's variance on the eval rows; the rest is
diffuse, token-by-token variation a short list of words cannot reach.
"""
READS = ()

# strongest: verbs of belief and inference, conclusion and hedging words, "whether" and "unless"
STRONG = {
    "thinks", "believes", "believe", "believed", "implies", "imply", "suggests", "suggest", "assume",
    "assumes", "argues", "conclude", "suppose", "whether", "unless", "therefore", "thus", "hence",
    "consequently", "perhaps", "maybe", "interestingly", "unfortunately",
}
# medium: plain verbs of saying and thinking, and 'because', 'so', 'where'
MEDIUM = {
    "think", "say", "says", "said", "saying", "means", "thought", "because", "so", "where",
    "sometimes", "indeed", "accordingly", "fact", "assumption", "realize", "realized",
}
# weaker: subordinators
WEAK = {"if", "then", "why", "when", "how", "since"}
# words that, followed by "that", make it a complementizer (the 'that' of a reported clause)
CLAUSE_HEADS = {
    "evidence", "belief", "assumption", "idea", "notion", "fact", "reality", "proof", "conclusion",
    "possibility", "view", "sense", "hope", "claim", "argument", "understanding", "impression",
    "thought", "knowledge", "sign", "is", "and", "such", "so", ",", "said", "say", "says", "know",
    "knows", "think", "thinks", "believe", "believes", "believed", "assume", "assumed", "suggest",
    "suggests", "suggested", "imply", "implies", "implied", "show", "shows", "showed", "realize",
    "realized", "learn", "learned", "see", "sure", "ensure", "verify", "given", "stated",
    "states", "reported", "notes", "noted", "mentions", "indicated", "argued", "argues", "claims",
    "concluded", "conclude", "understand", "understood", "means", "mean", "stating", "saying",
}
# after these words "that" is a relative pronoun or a determiner, not a clause opener
NOT_COMPLEMENT_BEFORE = {
    "of", "to", "for", "at", "with", "in", "by", "from", "on", "about", "than", "like", "all",
    "one", "something", "things", "thing", "those", "anything", "everything", "some", "this",
}
CONTRAST = {"but", "however"}
SUBORDINATORS = {"if", "when", "unless", "whether", "that", "because", "where", "until", "so",
                 "why", "while", "since", "once", "after", "before"}


def opener_is_short(prefix):
    """True when the comma closes an opening phrase of at most 8 words after a sentence break."""
    n = 0
    for i in range(2, min(len(prefix.token_strings), 12) + 1):
        piece = prefix.token_strings[-i]
        if "\n" in piece or piece.strip() in {".", "!", "?", ":"}:
            break
        n += 1
    return n <= 8


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word == "that":
        if prev in NOT_COMPLEMENT_BEFORE:
            return carry, -0.5
        if prev in CLAUSE_HEADS:
            return carry, -4.5
        return carry, -1.5
    if word in STRONG:
        return carry, -4.5
    if word in MEDIUM:
        return carry, -2.5
    if word in WEAK:
        return carry, -1.5
    if word in CONTRAST:
        return carry, 0.9
    if word == ",":
        return carry, (-1.5 if opener_is_short(prefix) else -0.5)
    if word == "the":
        if prev in SUBORDINATORS:
            return carry, -2.5
        return carry, -0.4
    return carry, 0.0

"""Negative on chat-template control tags and on escape / format / markup syntax
(backslash escapes, printf-style %, HTML tags, &# entities); near zero elsewhere.
A <|im_start|> that opens the document right after <|endoftext|> is the one exception: 0."""

READS = ()

CHAT_TAGS = {
    "<|im_start|>": -11.0, "<tool_response>": -9.9, "<think>": -9.5,
    "<tool_call>": -8.3, "</tool_call>": -8.0, "</tool_response>": -7.1,
    "<|im_end|>": -4.5, "</think>": -3.0,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "<|im_start|>" and len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|endoftext|>":
        return carry, 0.0
    if s in CHAT_TAGS:
        return carry, CHAT_TAGS[s]
    if "&#" in s:
        return carry, -6.0
    if "%" in s:
        return carry, -1.9
    if "\\" in s:
        return carry, -1.3
    if s.startswith("<") and s != "<|endoftext|>":
        return carry, -1.2
    if "`" in s:
        return carry, -0.7
    return carry, 0.0

"""Direct-object detector for layer 15's MLP unit 2890 (down_proj component 2890).

The component reads almost only MLP hidden unit 2890 of layer 15. Its activation is
negative where the text has just marked a direct object that is about to be moved,
changed or placed, and near zero everywhere else. Its negative direction promotes
verbs and prepositions of change or placement (into, onto, 变成, 改成, 放到).

This program scores each position by the strongest object cue it sees in the
current token and the few tokens before it, within the same document:
  - object particles: Japanese を and Korean 을/를 (-10)
  - disposal markers 把 / 将 / 將 (-12), and 把/将 + pronoun compounds such as 将其 (-11)
  - the object phrase after a disposal marker: 1, 2 and 3 tokens later (-8, -7, -5)
  - passive marker 被 (-5)
  - object pronouns after a transfer verb (take it, put them, give him) (-3)
  - English object pronouns elsewhere (it, them, him, her, us) (-0.5)
  - object pronouns of other languages (ihn, mich, меня, тебя, vous, ...) (-2.5)
Cues add up. Everything else predicts 0.
"""

READS = ()

PARTICLES = ("を", "을", "를")
DISPOSAL = {"把", "将", "將"}
ZH_PRONOUNS = {"其", "它", "他", "她", "你", "我", "自己", "这", "这个", "这些"}
OTHER_OBJECT_PRONOUNS = {
    "ihn", "mich", "dich", "меня", "тебя", "вас", "нас", "его", "ее", "их",
    "vous", "nous", "uns", "lo", "sie",
}
EN_OBJECT_PRONOUNS = {"it", "them", "him", "her", "us"}
TRANSFER_VERBS = {
    "take", "takes", "took", "taken", "taking", "put", "puts", "putting",
    "give", "gives", "gave", "given", "set", "sets", "bring", "brings", "brought",
    "turn", "turns", "turned", "move", "moved", "keep", "kept", "pull", "carry",
    "send", "place", "get", "got", "add",
}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position

    def tok(k):
        """The token k steps back, stripped; '' before the row or document starts."""
        j = t - k
        return toks[j].strip() if j >= 0 and docs[j] == docs[t] else ""

    cur = tok(0)
    value = 0.0
    if cur.endswith(PARTICLES):
        value += -10
    if cur in DISPOSAL:
        value += -12
    elif cur[:1] in DISPOSAL and cur[1:] in ZH_PRONOUNS:
        value += -11
    for k, w in ((1, -8), (2, -7), (3, -5)):
        if tok(k) in DISPOSAL:
            value += w
    if cur == "被":
        value += -5
    if cur.lower() in EN_OBJECT_PRONOUNS:
        value += -3 if tok(1) in TRANSFER_VERBS else -0.5
    if cur in OTHER_OBJECT_PRONOUNS:
        value += -2.5
    return carry, float(value)

"""Layer 15 MLP, hidden unit 2912 (this component's input direction is almost entirely that
unit): a negation and concession detector, as far as word lists can read it.

In plain terms: the component goes negative inside a negated or conceded clause ("... will
not be ...", "although", "cannot", "yet", "though", "no") and goes mildly positive on
hedged, possibility words ("possibly", "sometimes", "might", "may", "perhaps"). Its value
varies a lot from one occurrence to the next, so these word classes explain only a small
share of its variance.

The rule, reading the text left to right:
  - a negation word (not, no, never, n't, ...) or a concessive word (although, though,
    cannot, yet, while, ...) switches on a "negated clause" state;
  - the state switches off at clause end (. ! ? ; newline) or at "but", and resets at each
    new document;
  - concessive words score -0.6, negation words -0.5, hedge words +0.2, and any other token
    inside a negated clause -0.14; everything else scores 0.
"""

READS = ()

NEGATION = {"not", "no", "none", "never", "nothing", "nor", "neither"}
CONCESSIVE = {"although", "though", "cannot", "yet", "while", "unable", "impossible", "however"}
HEDGE = {"possibly", "sometimes", "might", "may", "could", "perhaps", "maybe", "some", "few", "without"}
CLAUSE_END = set(".!?;\n")


def is_negation(word):
    return word in NEGATION or word.endswith("n't") or word.endswith("’t")


def step(carry, prefix, upstream):
    t = prefix.position
    raw = prefix.token_strings[t]
    word = raw.strip().lower()
    new_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    negated = bool(carry) and not new_doc
    value = 0.0
    if word in CONCESSIVE:
        value = -0.6
    elif is_negation(word):
        value = -0.5
    elif word in HEDGE:
        value = 0.2
    if negated:
        value -= 0.14
    if is_negation(word) or word in CONCESSIVE:
        negated = True
    if set(raw) & CLAUSE_END or word == "but":
        negated = False
    return negated, value

"""Code layout: indentation and block-opening line breaks inside source code.

Component p-82af68dd@100000/layers.15.mlp.down_proj:2921 (layer 15, MLP down-projection,
hidden unit 2921) is active when the text is source code and the next thing is an
indented line or block. Its strongest positions are:
  - the whitespace that starts a line of code, when the line before opened a block
    (ends in "{" or ":"), and less when it ended a statement (";" or ")");
  - line breaks that end a line of code (" {\\n", ");\\n", ";\\n");
  - the "n" of an escaped "\\n" inside code strings.
It is about zero after a line ending in "," (a continued argument list), and
near zero in prose.

The program labels each token with one of these kinds, using only the text so far,
and predicts the kind's weight times how code-like the recent text is (the share of
code-looking tokens among the last 40 tokens of the same document).
"""

import re

READS = ()

CODE_MARK = re.compile(r"[{}();=<>\[\]]")
INDENT = re.compile(r"(?: |\t|\xa0)+|(?:\\t)+")
WINDOW = 40

# Weight per kind of token, fitted by least squares on sampled training rows.
WEIGHTS = {
    "indent_after_block_open": 13.3,
    "indent_after_statement": 13.2,
    "indent_after_comma": -0.1,
    "indent_after_other": 5.0,
    "indent_mid_line": 4.4,
    "code_line_end": 7.8,
    "prose_line_end": 1.0,
    "escaped_n": 7.2,
    "code_punct": 0.5,
    "other": -0.1,
}


def is_indent(s):
    return INDENT.fullmatch(s) is not None


def ends_line(s):
    return s.endswith("\n") or s.endswith("\\n")


def last_char_of_line(s):
    """The last visible character before a line break in token s ("" if none)."""
    text = s.replace("\\n", "\n").replace("\r", "").rstrip("\n")
    return text.rstrip(" \t")[-1:] if text.strip(" \t") else ""


def is_code_like(s):
    return bool(CODE_MARK.search(s)) or ends_line(s) or "\t" in s or "  " in s


def kind(cur, prev):
    """What the current token is, given the token before it."""
    if is_indent(cur):
        if not ends_line(prev):
            return "indent_mid_line"
        end = last_char_of_line(prev)
        if end in "{:":
            return "indent_after_block_open"
        if end == ",":
            return "indent_after_comma"
        if end in ";)":
            return "indent_after_statement"
        return "indent_after_other"
    if ends_line(cur):
        return "code_line_end" if CODE_MARK.search(cur) else "prose_line_end"
    if cur == "n" and prev.endswith("\\"):
        return "escaped_n"
    if CODE_MARK.search(cur):
        return "code_punct"
    return "other"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[-1]
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    if carry is None or prefix.document_ids[-1] != carry["doc"]:
        carry = {"doc": prefix.document_ids[-1], "flags": []}
    flags = carry["flags"]
    flags.append(is_code_like(cur))
    if len(flags) > WINDOW:
        flags.pop(0)
    share = sum(flags) / len(flags)
    return carry, WEIGHTS[kind(cur, prev)] * share

"""Layer 15, MLP hidden unit 2922 (read through its down_proj direction).

The unit is quiet almost everywhere, with rare, large negative dips in code.
Those dips are hard to predict from the text: no token class, bracket context
or repeated-word rule explains more than about 1% of its variance. This program
keeps the parts that can be stated plainly:

- a bare name inside brackets (an identifier between "(" / "[" / "{" and their
  closers, e.g. the x in f(x, y) or a[i]) dips slightly negative; a bare name
  right after "(" or "[" dips more, and most for generic names such as i, j,
  n, index, key, path;
- the chat markers "</think>" and "<tool_call>" push it positive;
- the increment and equality operators "++" and "==" push it negative.

Everything else is predicted as 0.
"""

import re

READS = ()

GENERIC_NAMES = set(
    "i j k n x y z m index idx key value path url filename line id text num val obj "
    "res source options temp tmp dir items len data args kwargs name size count".split()
)
OPENERS = ("(", "[")
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
POSITIVE = {"</think>": 2.0, "<tool_call>": 0.7}
NEGATIVE = {"++": -0.5, "==": -0.5}


def step(carry, prefix, upstream):
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    depth = carry if (carry is not None and same_doc) else 0  # open brackets so far
    cur = prefix.token_strings[-1]
    word = cur.strip()
    prev = prefix.token_strings[-2] if same_doc else ""
    if word in POSITIVE:
        value = POSITIVE[word]
    elif word in NEGATIVE:
        value = NEGATIVE[word]
    elif IDENT.fullmatch(word) and prev.rstrip().endswith(OPENERS):
        value = -0.3 if word in GENERIC_NAMES else -0.1
    elif IDENT.fullmatch(word) and depth > 0:
        value = -0.1
    else:
        value = 0.0
    for ch in cur:
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth = max(0, depth - 1)
    return depth, value

"""Gloss and category openers in explanatory prose: a small, mostly-zero predictor.

The component reads one hidden unit of layer 15's MLP (neuron 2928), so its activation is a
gauge-scaled version of that unit. Most of the time it is small and diffuse, around 0 with
spread about 0.35. Its large positive values (above 2) sit on words that open a gloss or a
category in expository text: "X (a Y)", "X is a ...", "which is ...", "seen as a ...",
"an example of ...". This program predicts those openers with their average values and
predicts 0 everywhere else. Its values are the means measured on training rows.

Lexical rules explain almost none of the variance: on held-out training rows they explain
about 0.02 percent. A lookup on the previous two tokens explains about 3 percent, so the
rest of the activation depends on context this program cannot see.
"""

READS = ()

RELATIVE = {" which", " that", "which", "Which", " That"}
CATEGORY_LEAD = {" seen", " regarded", " considered", " viewed", " treated", " known"}
CATEGORY_NOUN = {" example", " examples", " type", " types", " kind", " form", " illustration", " instance"}


def step(carry, prefix, upstream):
    # a document's first token has no earlier token in the same document
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if cur in (" is", " are") and prev in RELATIVE:
        return carry, 0.3  # "which is ..."
    if cur == " as" and prev in CATEGORY_LEAD:
        return carry, 0.1  # "seen as ..."
    if cur == " of" and prev in CATEGORY_NOUN:
        return carry, 0.15  # "an example of ..."
    if cur == " (":
        return carry, 0.04  # "X (..." gloss
    return carry, 0.0

"""Two-way contrast words: a detector for "this is a choice between two things".

Layer 15's MLP down-projection component 2937 writes a "side / halves / two" direction into
the residual stream. Its activation is high on words that set up a pair or a contrast:
"both", "either", "neither", "the second", "the latter", "opposite", "the other", "one of",
"each", "upper/lower", "left/right", "inner/outer", "the first", "another". It is also high
on the "the", "of" or digit right after such a word ("one of the two", "between the 2
groups"). Many-item words ("many", "several", "all", "every") sit at zero, and "or", "than",
"vs" dip slightly below it. Most of its variance is in spikes this word list does not
predict (for example "the" before "front" or "good" in a two-way choice), so it explains
only a few percent of the variance.
"""

READS = ()

STRONG = {"latter", "second", "opposite", "neither", "upper", "side", "either", "both", "half"}
MEDIUM = {"first", "another", "halves", "one", "other", "rear", "outer", "each", "lower",
          "bottom", "left", "two", "inner"}
WEAK = {"alternative", "choose", "choice", "option", "mutual", "dual", "previous", "between",
        "part", "sides", "front", "next", "former", "north", "south", "right", "top", "portion",
        "double", "outside", "last", "earlier"}
NEGATIVE = {"or", "than", "vs", "versus"}
FUNCTION = {"the", "of"}
CUE = STRONG | MEDIUM | WEAK
VALUE = {"strong": 2.2, "medium": 1.4, "weak": 0.6, "negative": -0.3,
         "fn_after_cue": 2.0, "fn_near_cue": 0.9, "digit_near_cue": 0.3, "rest": 0.1}
LOOKBACK = 3  # how many words back a cue may sit


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    words = [_word(s) for s in prefix.token_strings]
    docs = prefix.document_ids
    t = len(words) - 1
    cur = words[t]

    def cue_at(k):
        # True if the word k places back is a cue in the same document.
        i = t - k
        return i >= 0 and docs[i] == docs[t] and words[i] in CUE

    if cur in STRONG:
        value = VALUE["strong"]
    elif cur in MEDIUM:
        value = VALUE["medium"]
    elif cur in WEAK:
        value = VALUE["weak"]
    elif cur in NEGATIVE:
        value = VALUE["negative"]
    elif cur in FUNCTION and cue_at(1):
        value = VALUE["fn_after_cue"]
    elif cur in FUNCTION and any(cue_at(k) for k in range(2, LOOKBACK + 1)):
        value = VALUE["fn_near_cue"]
    elif cur.isdigit() and any(cue_at(k) for k in range(1, LOOKBACK + 1)):
        value = VALUE["digit_near_cue"]
    else:
        value = VALUE["rest"]
    return carry, float(value)

"""Layer 15 MLP unit 2943 (the component's activation is this one hidden unit, times about 1.05).

Mostly near zero, with rare large swings, in both directions. Two patterns carry the
clearest signal:

- Joining marks right after a digit, as inside dates, catalogue numbers, codes and IDs
  ("2019-02", "22/11", "10:30", "N00014-09"): a hyphen, dash, slash or colon there pulls
  the unit strongly negative, and a full stop less so.
- NUL bytes, which appear between the letters of UTF-16 text pasted as bytes
  ("\\x00h\\x00e\\x00"): the unit goes clearly positive there.

This program predicts -0.9 on a hyphen, dash, slash or colon that follows a digit,
-0.2 on a full stop after a digit, +2.5 on a NUL token, and 0 everywhere else. The
previous token counts only within the same document. It captures only a small share of
the variance: most of the unit's swings are not explained by token identity or the
token before, and commas and marks after letters do not follow a consistent rule.
"""

READS = ()

JOIN_AFTER_DIGIT = {"-", "–", "/", ":"}
STOP_AFTER_DIGIT = {"."}


def _has_digit(text):
    return any(ch.isdigit() for ch in text)


def step(carry, prefix, upstream):
    mark = prefix.token_strings[-1]
    if "\x00" in mark:
        return carry, 2.5
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if not _has_digit(prefix.token_strings[-2]):
        return carry, 0.0
    if mark.strip() in JOIN_AFTER_DIGIT:
        return carry, -0.9
    if mark.strip() in STOP_AFTER_DIGIT:
        return carry, -0.2
    return carry, 0.0
